export const SELECTION_KIND = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | { readonly kind: typeof SELECTION_KIND.closed }
  | { readonly kind: typeof SELECTION_KIND.one; readonly index: number }
  | { readonly kind: typeof SELECTION_KIND.mismatch; readonly first: number;
      readonly second: number; readonly remainingMs: number };

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return {
    board, deck: generateDeck(board), matched: [], selection: { kind: SELECTION_KIND.closed },
    moves: 0, elapsedMs: 0, started: false,
  };
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}
import { isWon, SELECTION_KIND } from './state.ts';
import type { GameState } from './state.ts';

export const MOVE_CAP = 999_999;
export const ELAPSED_CAP = 359_999_999;
export const MISMATCH_MS = 800;

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length ||
      isWon(state) || state.matched.includes(index)) return state;
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION_KIND.closed:
      return { ...state, started: true, selection: { kind: SELECTION_KIND.one, index } };
    case SELECTION_KIND.one: {
      if (selection.index === index) return state;
      const moves = Math.min(MOVE_CAP, state.moves + 1);
      if (state.deck[selection.index] === state.deck[index]) {
        return { ...state, moves, matched: [...state.matched, selection.index, index],
          selection: { kind: SELECTION_KIND.closed } };
      }
      return { ...state, moves, selection: { kind: SELECTION_KIND.mismatch,
        first: selection.index, second: index, remainingMs: MISMATCH_MS } };
    }
    case SELECTION_KIND.mismatch:
      return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(ELAPSED_CAP, state.elapsedMs + milliseconds);
  const selection = state.selection;
  if (selection.kind === SELECTION_KIND.mismatch) {
    const remainingMs = selection.remainingMs - milliseconds;
    return { ...state, elapsedMs, selection: remainingMs > 0
      ? { ...selection, remainingMs } : { kind: SELECTION_KIND.closed } };
  }
  return elapsedMs === state.elapsedMs ? state : { ...state, elapsedMs };
}

import type { BoardDescription } from './boardCode.ts';

const MODULUS = 2_147_483_647;
const RANDOM_VALUES = MODULUS - 1;

export function nextRandom(state: number): number {
  return (state * 16_807) % MODULUS;
}

export function drawBounded(state: number, bound: number): { state: number; value: number } {
  const limit = Math.floor(RANDOM_VALUES / bound) * bound;
  let next = nextRandom(state);
  while (next - 1 >= limit) next = nextRandom(next);
  return { state: next, value: (next - 1) % bound };
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, index) => Math.floor(index / 2));
  let randomState = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const draw = drawBounded(randomState, index + 1);
    randomState = draw.state;
    const current = deck[index];
    const chosen = deck[draw.value];
    if (current === undefined || chosen === undefined) throw new Error('Invalid shuffle position');
    deck[index] = chosen;
    deck[draw.value] = current;
  }
  return Object.freeze(deck);
}
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function exactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(value);
  return actual.length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

export function isNonnegativeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

export function parseLimitedJson(text: string, byteLimit: number): unknown {
  if (text.length > byteLimit || new TextEncoder().encode(text).length > byteLimit) return null;
  try { const value: unknown = JSON.parse(text); return value; } catch { return null; }
}
