    expect(turnAnnouncement(next, miss)).toBe('No match. Cards close after a short pause.');
    expect(turnAnnouncement(miss, advanceGame(miss, 800))).toBeNull();
  });

  it('ignores first reveals, repeated cards and clock updates', () => {
