button, select, input, textarea {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
}
button, select { min-height: 44px; padding: 8px 16px; }
button { cursor: pointer; }
button:hover { border-color: var(--text); }
button:focus-visible, select:focus-visible, input:focus-visible,
textarea:focus-visible, summary:focus-visible { outline: 3px solid #FFFFFF; outline-offset: 2px; }
.game { width: 100%; max-width: 1120px; margin: 0 auto; padding: 16px; }
.game-header { margin-bottom: 24px; }
.game-header h1 { font-size: 24px; line-height: 32px; font-weight: 750; }
.game-header p { color: var(--secondary); font-size: 14px; margin-top: 4px; }
.play-area { min-width: 0; margin-top: 16px; }
.board-help { color: var(--secondary); font-size: 14px; margin-top: 12px; }
.pause-note { color: var(--secondary); font-size: 14px; margin-bottom: 8px; }
